"""Generate zml/kernels/moe/megamoe/layout_test.zig from DeepGEMM ground truth (layout_gt.json)."""
import json, sys
gt = json.load(open(sys.argv[1]))
out = open(sys.argv[2], 'w')
w = out.write
w('''//! Tests of `layout.zig` against DeepGEMM's own numbers. Generated by
//! `scripts/gen_layout_test.py` from `gt/layout_gt.json`, the output of `gt/layout_gt.cu`
//! (DeepGEMM's layout/scheduler headers, its host heuristics and buffer-layout functions and the
//! kernel's SharedStorage, compiled with nvcc). Do not edit the tables by hand.
const std = @import("std");

const L = @import("layout.zig");

''')
s = gt['signals']
w('const signals_gt = .{\n')
for k, v in s.items():
    w(f'    .{{ "{k}", {v} }},\n')
w('};\n\n')
w('''test "MegaMoESignals, TokenSrcMetadata and TaskInfo match DeepGEMM" {
    inline for (signals_gt) |e| {
        if (comptime std.mem.eql(u8, e[0], "sizeof")) {
            try std.testing.expectEqual(@as(u64, e[1]), @sizeOf(L.Signals));
        } else if (comptime std.mem.eql(u8, e[0], "sizeof_token_src_metadata")) {
            try std.testing.expectEqual(@as(u64, e[1]), @sizeOf(L.TokenSrcMetadata));
        } else if (comptime std.mem.eql(u8, e[0], "sizeof_task_info")) {
            try std.testing.expectEqual(@as(u64, e[1]), @sizeOf(L.TaskInfo));
        } else if (comptime std.mem.eql(u8, e[0], "alignof_task_info")) {
            try std.testing.expectEqual(@as(u64, e[1]), @alignOf(L.TaskInfo));
        } else {
            try std.testing.expectEqual(@as(u64, e[1]), L.Signals.offset(e[0]));
        }
    }
}

''')
# buffers
w('/// num_sms, R, E, T_req, T, topk, H, I, shared, layout[21], workspace bytes, pool tokens, shared l2 pool blocks, shared sf tokens\n')
w('const buffers_gt = [_][34]u64{\n')
for b in gt['buffers']:
    row = [b['num_sms'], b['num_ranks'], b['num_experts'], b['num_max_tokens_per_rank_req'], b['num_max_tokens_per_rank'], b['num_topk'], b['hidden'], b['intermediate'], b['num_shared_experts']] + b['layout'] + [b['workspace_bytes'], b['num_max_pool_tokens'], b['num_shared_l2_pool_blocks'], b['shared_sf_tokens']]
    assert len(row) == 34, len(row)
    w('    .{ ' + ', '.join(str(x) for x in row) + ' },\n')
w('};\n\n')
w('''test "symmetric buffer layout matches build_symm_buffer_layout" {
    for (buffers_gt) |g| {
        const T = L.alignTokens(@intCast(g[3]));
        try std.testing.expectEqual(g[4], T);
        const shape: L.Shape = .{
            .num_ranks = @intCast(g[1]),
            .num_experts = @intCast(g[2]),
            .num_topk = @intCast(g[5]),
            .hidden = @intCast(g[6]),
            .intermediate_hidden = @intCast(g[7]),
            .num_shared_experts = @intCast(g[8]),
            .num_max_tokens_per_rank = T,
        };
        const lay: L.SymmBufferLayout = .init(shape, @intCast(g[0]));
        const b = lay.buffer;
        const l = g[9..30];
        try std.testing.expectEqual(l[0], lay.numBytes());
        try std.testing.expectEqual(l[1], b.input_token.offset);
        try std.testing.expectEqual(l[2], b.input_sf.offset);
        try std.testing.expectEqual(l[3], b.input_topk_idx.offset);
        try std.testing.expectEqual(l[4], b.input_topk_weights.offset);
        try std.testing.expectEqual(l[5], b.shared_l1_sf.offset);
        try std.testing.expectEqual(l[6], b.shared_l2_token.offset);
        try std.testing.expectEqual(l[7], b.shared_l2_sf.offset);
        try std.testing.expectEqual(l[8], b.l1_token.offset);
        try std.testing.expectEqual(l[9], b.l1_sf.offset);
        try std.testing.expectEqual(l[10], b.l2_token.offset);
        try std.testing.expectEqual(l[11], b.l2_sf.offset);
        try std.testing.expectEqual(l[13], T);
        try std.testing.expectEqual(l[18], shape.sharedIntermediateHidden());
        try std.testing.expectEqual(l[19], lay.num_ring_tokens);
        try std.testing.expectEqual(l[20], lay.num_sf_ring_tokens);
        try std.testing.expectEqual(g[30], b.workspace.numBytes());
        try std.testing.expectEqual(g[31], b.workspace.num_max_pool_tokens);
        try std.testing.expectEqual(g[32], b.workspace.num_shared_l2_pool_blocks);
        try std.testing.expectEqual(g[33], L.numMaxSharedSfTokens(T));
    }
}

''')
w('/// M, num_sms, H, I, get_num_max_live_pool_blocks, get_num_l1_warmup_waves(M, sms/2, 2I/256, H/256)\n')
w('const live_gt = [_][6]i32{\n')
for x in gt['live']:
    w('    .{ ' + ', '.join(str(v) for v in x) + ' },\n')
w('};\n\n')
w('''test "ring capacity matches sched::get_num_max_live_pool_blocks" {
    for (live_gt) |g| {
        try std.testing.expectEqual(g[4], L.numMaxLivePoolBlocks(g[0], g[1], g[2], g[3]));
        try std.testing.expectEqual(g[5], L.numL1WarmupWaves(g[0], @divTrunc(g[1], 2), @divTrunc(g[3] * 2, 256), @divTrunc(g[2], 256)));
    }
}

''')
w('/// R, E, T, topk, num_tokens, H, block_m, store_block_m_l1, store_block_m_l2, block_k, sf_block_m, pull bytes, stages, smem\n')
w('const configs_gt = [_][14]u32{\n')
for x in gt['configs']:
    w('    .{ ' + ', '.join(str(v) for v in x) + ' },\n')
w('};\n\n')
w('''test "block and pipeline configs match get_mega_moe_config" {
    for (configs_gt) |g| {
        const bc = L.blockConfig(g[0], g[1], g[3], g[4], .mxfp8fp4);
        try std.testing.expectEqual(g[6], bc.block_m);
        try std.testing.expectEqual(g[7], bc.store_block_m_l1);
        try std.testing.expectEqual(g[8], bc.store_block_m_l2);
        try std.testing.expectEqual(g[9], bc.block_k);
        const sf_block_m = L.alignUp(bc.block_m, 128);
        try std.testing.expectEqual(g[10], sf_block_m);
        var pull = g[5];
        while (pull > 8192) pull /= 2;
        try std.testing.expectEqual(g[11], pull);
        const p = L.pipelineConfig(L.smem_capacity, g[1], bc.block_m, 128, bc.block_k, pull, bc.store_block_m_l1, bc.store_block_m_l2, sf_block_m, 128, 32, 4, 8, .mxfp8fp4);
        try std.testing.expectEqual(g[12], p.num_stages);
        try std.testing.expectEqual(g[13], p.smem_size);
    }
}

''')
fields = ['expert_token_count', 'dispatch_send_buffer', 'smem_d', 'smem_a', 'smem_b', 'smem_sfa', 'smem_sfb', 'amax_reduction', 'task_infos', 'dispatch_barriers', 'full_barriers', 'empty_barriers', 'tmem_full_barriers', 'tmem_empty_barriers', 'combine_barriers', 'task_info_full_barriers', 'task_info_empty_barriers', 'tmem_ptr_in_smem']
w('const smem_fields = .{ ' + ', '.join(f'"{f}"' for f in fields) + ' };\n')
w('/// num_experts, block_m, sbm1, sbm2, stages, pull, fp8 weights, offsets of `smem_fields`, sizeof(smem_d), sizeof\n')
w(f'const smem_gt = [_][{7 + len(fields) + 2}]u32{{\n')
for i, x in enumerate(gt['smem']):
    fp8 = 1 if i == len(gt['smem']) - 1 else 0
    row = [x['num_experts'], x['block_m'], x['sbm1'], x['sbm2'], x['stages'], x['pull'], fp8] + [x[f] for f in fields] + [x['sizeof_smem_d'], x['sizeof']]
    w('    .{ ' + ', '.join(str(v) for v in row) + ' },\n')
w('};\n\n')
w('''test "SharedStorage offsets match the kernel's struct" {
    for (smem_gt) |g| {
        const T = 9600;
        const shape: L.Shape = .{ .num_ranks = 2, .num_experts = g[0], .num_topk = 6, .hidden = 5120, .intermediate_hidden = 2304, .num_shared_experts = 1, .num_max_tokens_per_rank = T };
        const cfg: L.Config = .{
            .block_m = g[1],
            .block_k = 128,
            .load_block_m = g[1] / 2,
            .store_block_m_l1 = g[2],
            .store_block_m_l2 = g[3],
            .sf_block_m = L.alignUp(g[1], 128),
            .sf_block_n = 128,
            .num_ring_tokens = 21120,
            .num_sf_ring_tokens = 337920,
            .num_stages = g[4],
            .smem_size = 0,
            .num_bytes_per_pull = g[5],
        };
        const s = L.SharedStorage.init(.{ .shape = shape, .cfg = cfg, .num_sms = 152, .weight_type = if (g[6] == 1) .fp8 else .fp4_unpacked });
        inline for (smem_fields, 0..) |f, i| try std.testing.expectEqual(g[7 + i], @field(s, f));
        try std.testing.expectEqual(g[7 + smem_fields.len], s.smem_d_bytes);
        try std.testing.expectEqual(g[8 + smem_fields.len], s.size);
    }
}
''')
out.close()
